import{_ as r,E as i,h as s,c as o,b as a,f as n,H as c,a4 as d}from"./chunks/framework.B_fYP6Of.js";const b=JSON.parse('{"title":"Browser verification","description":"Read a Chrome CI receipt, inspect documentation screenshots and distinguish a successful browser check from a live publication or an accessibility audit.","frontmatter":{"title":"Browser verification","description":"Read a Chrome CI receipt, inspect documentation screenshots and distinguish a successful browser check from a live publication or an accessibility audit.","teaser":"Chrome can verify that a page opened and its navigation worked. The review artifact lets you inspect the result and say exactly what the check covered."},"headers":[],"relativePath":"reference/browser-review.md","filePath":"reference/browser-review.md"}'),h={name:"reference/browser-review.md"};function l(p,e,u,m,v,w){const t=i("LabArticleHeader");return s(),o("div",null,[e[0]||(e[0]=a("h1",{id:"review-the-rendered-site",tabindex:"-1"},[n("Review the rendered site "),a("a",{class:"header-anchor",href:"#review-the-rendered-site","aria-label":'Permalink to "Review the rendered site"'},"​")],-1)),c(t),e[1]||(e[1]=d('<p>If a student says a page is unreadable on a narrow screen, begin with the specific route and viewport. Find the corresponding receipt and image, check the recorded browser version, and look at the actual line wrapping and navigation. A local screenshot helps diagnose the issue even when publication is a separate question.</p><p>The <strong>Documentation browser review</strong> workflow builds VitePress and serves its static output over isolated loopback HTTP in CI. It uses the runner&#39;s installed Chrome and records the exact browser version in the receipt. There is no provider credential or new application dependency.</p><h2 id="automated-checks" tabindex="-1">Automated checks <a class="header-anchor" href="#automated-checks" aria-label="Permalink to &quot;Automated checks&quot;">​</a></h2><p>Seven routes are inspected at desktop and narrow-screen sizes and in dark mode: homepage, vision, walkthrough, design, build, glossary and twelve-factor guidance. Each must have one H1, a source-revision marker and no page-level horizontal overflow.</p><p>The review also opens local search, checks results remain under the repository path, opens mobile navigation and rejects reported JavaScript exceptions. It captures screenshots and a JSON receipt in the <code>documentation-browser-review</code> artifact.</p><h2 id="inspect-the-artifact" tabindex="-1">Inspect the artifact <a class="header-anchor" href="#inspect-the-artifact" aria-label="Permalink to &quot;Inspect the artifact&quot;">​</a></h2><p>Pick one task before examining a screenshot: can a reader find the next section, recognize the page title, or read a table without moving the entire page sideways? Record what you observed at that viewport alongside the automated assertions.</p><p>Review the home screenshots in desktop, mobile and dark layouts and the vision-page screenshot. Automated layout checks do not judge whether a visual hierarchy or reading path is useful. Record that human/assistant inspection separately.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>This is not a Safari test, a screen-reader audit, production HTTPS validation or universal accessibility certification. The runner browser is recorded, not claimed to be identical across future runs. Static source/build checks, browser review and live Pages publication are different gates.</p><p>The <a href="./../project/setup">publishing workflow</a> separately verifies public responses and the deployed revision. <a href="./documentation-map">Documentation map</a>.</p>',11))])}const g=r(h,[["render",l]]);export{b as __pageData,g as default};
